static bool inputCaptureDefaultHcMotionIdentity(const MachineIdentity& identity) {
    const auto* recipe=ymcc::hc_default_motion::find(identity.deviceClass);
    if(!recipe||!identity.resolved||!identity.gyroMatrixId.empty()||!identity.accelMatrixId.empty()) return false;
    const auto manufacturer=normalizeHcDmi(identity.manufacturer),product=normalizeHcDmi(identity.product);
    if(identity.family==YmccFamily::Gpd&&manufacturer=="GPD")
        return (identity.deviceClass=="HandheldCompanion.Devices.GPDWin2"&&product=="WIN2") ||
            (identity.deviceClass=="HandheldCompanion.Devices.GPDWin3"&&product=="G1618-03");
    return identity.family==YmccFamily::ValveSteamMachine&&manufacturer=="VALVE"&&product=="FREMONT"&&
        identity.deviceClass=="HandheldCompanion.Devices.SteamMachine";
}

static bool inputCaptureDefaultHcMotionSelectorBound() {
    if(!inputCaptureDefaultHcMotionIdentity(g_machineIdentity)||!g_hcMotionSelector.attempted||!g_hcMotionSelector.resolved) return false;
    const auto* recipe=ymcc::capabilities::motion::consume(g_hcMotionSelector.unifiedBinding,
        ymcc::capabilities::motion::Kind::Default, ymcc::hc_default_motion::recipes);
    if(!recipe || recipe->deviceClass != g_machineIdentity.deviceClass) return false;
    return g_hcMotionSelector.nativeFamily==static_cast<int>(g_machineIdentity.family)&&g_hcMotionSelector.deviceClass==g_machineIdentity.deviceClass&&
        g_hcMotionSelector.dmiManufacturer==g_machineIdentity.manufacturer&&g_hcMotionSelector.dmiProduct==g_machineIdentity.product&&
        g_hcMotionSelector.dmiSystemProduct==g_machineIdentity.systemProduct&&g_hcMotionSelector.dmiProcessor==g_machineIdentity.processor&&
        g_hcMotionSelector.dmiSystemVersion==g_machineIdentity.systemVersion&&g_hcMotionSelector.selectorId==recipe->selectorId&&
        g_hcMotionSelector.gyroMatrixId==recipe->gyroMatrixId&&g_hcMotionSelector.accelMatrixId==recipe->accelMatrixId&&
        g_hcMotionSelector.matrixSourceSha256==recipe->sourceSha256;
}

static bool inputCaptureMotionSelectorBound() {
    if(!g_hcMotionSelector.resolved) return false;
    if(inputCaptureGenericHcMotionRecipe(g_machineIdentity))return inputCaptureGenericHcMotionSelectorBound();
    if(ymcc::hc_default_motion::find(g_machineIdentity.deviceClass)) return inputCaptureDefaultHcMotionSelectorBound();
    if (ymcc::hc_model_motion::find(g_machineIdentity.deviceClass)) return inputCaptureNewHcMotionSelectorBound();
    if (ymcc::hc_legacy_motion::containsClass(g_machineIdentity.deviceClass)) return inputCaptureLegacyHcMotionSelectorBound();
    return inputCapturePrivateHcMotionSelectorRecipe()!=nullptr;
}
